/** UI-to-transport integration with a synthetic desktop. Never calls a real API. */
public final class InteractionRegression extends Instrumentation {
    Activity app;Throwable failure;final List<String> paths=new CopyOnWriteArrayList<>();final List<JSONObject> writes=new CopyOnWriteArrayList<>();
    private interface Check{void run()throws Exception;}
    Object get(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
    void set(Object o,String name,Object value)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
    Object call(String name,Class<?>[] types,Object...args)throws Exception{Method m=app.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(app,args);}
    void ui(Check c)throws Exception{failure=null;runOnMainSync(()->{try{c.run();}catch(Throwable e){failure=e;}});if(failure!=null)throw new Exception(failure);waitForIdleSync();}
    void require(boolean value,String label){if(!value)throw new AssertionError(label);}
    void await(Check c)throws Exception{Throwable error=null;for(int i=0;i<70;i++){try{c.run();return;}catch(Throwable e){error=e;}SystemClock.sleep(100);}throw new Exception(error);}
    AccessibilityNodeInfo find(AccessibilityNodeInfo node,String text){if(node==null)return null;if(text.equals(String.valueOf(node.getText()))||text.equals(String.valueOf(node.getContentDescription())))return node;for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo r=find(node.getChild(i),text);if(r!=null)return r;}return null;}
    void click(String text)throws Exception{await(()->require(find(getUiAutomation().getRootInActiveWindow(),text)!=null,"visible: "+text));AccessibilityNodeInfo node=find(getUiAutomation().getRootInActiveWindow(),text);Rect bounds=new Rect();node.getBoundsInScreen(bounds);require(!bounds.isEmpty(),"bounds: "+text);long time=SystemClock.uptimeMillis();getUiAutomation().injectInputEvent(MotionEvent.obtain(time,time,MotionEvent.ACTION_DOWN,bounds.exactCenterX(),bounds.exactCenterY(),0),true);getUiAutomation().injectInputEvent(MotionEvent.obtain(time,time+80,MotionEvent.ACTION_UP,bounds.exactCenterX(),bounds.exactCenterY(),0),true);SystemClock.sleep(300);waitForIdleSync();}
    void shot(String name)throws Exception{SystemClock.sleep(3200);Bitmap b=getUiAutomation().takeScreenshot();File dir=new File(getTargetContext().getExternalFilesDir(null),"ui-captures");dir.mkdirs();try(OutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
    JSONObject file(String name,String mime,byte[] bytes)throws Exception{return new JSONObject().put("name",name).put("mime",mime).put("data",android.util.Base64.encodeToString(bytes,android.util.Base64.NO_WRAP));}
    void swipe(View view,float dx,float dy)throws Exception{Rect r=new Rect();view.getGlobalVisibleRect(r);float x=r.exactCenterX(),y=r.exactCenterY();long t=SystemClock.uptimeMillis();getUiAutomation().injectInputEvent(MotionEvent.obtain(t,t,0,x,y,0),true);for(int i=1;i<=8;i++){SystemClock.sleep(30);getUiAutomation().injectInputEvent(MotionEvent.obtain(t,SystemClock.uptimeMillis(),2,x+dx*i/8,y+dy*i/8,0),true);}getUiAutomation().injectInputEvent(MotionEvent.obtain(t,SystemClock.uptimeMillis(),1,x+dx,y+dy,0),true);SystemClock.sleep(700);waitForIdleSync();}
    @Override public void onCreate(Bundle args){super.onCreate(args);getTargetContext().getSharedPreferences("coding-remote",0).edit().clear().commit();getTargetContext().getSharedPreferences("ui",0).edit().putBoolean("notifications",false).putBoolean("overlay",false).putBoolean("resumeChat",false).putBoolean("show_codex",true).putBoolean("show_claude",true).putBoolean("show_deepseek",true).putBoolean("hideHeader",true).putString("theme","light").commit();start();}
    @Override public void onStart(){Bundle result=new Bundle();try{
        app=startActivitySync(new Intent().setClassName(getTargetContext(),"io.github.abyxs.codingremote.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
        JSONObject fixture=new JSONObject().put("connected",true).put("session",new JSONObject().put("id","fixture").put("title","回归会话").put("turnCount",3).put("status","idle").put("requests",new JSONArray())).put("messages",new JSONArray().put(new JSONObject().put("id","reply").put("role","assistant").put("text","回归回复\n历史入口应该位于标题下方。"))).put("history",new JSONObject().put("before",120).put("hasEarlier",true));
        JSONArray sessions=new JSONArray();for(int i=0;i<12;i++)sessions.put(new JSONObject().put("id","fixture"+i).put("title","回归会话 "+i).put("cwd","D:/demo").put("updatedAt",1));
        Class<?> transport=Class.forName("io.github.abyxs.codingremote.MainActivity$Transport");Object mock=Proxy.newProxyInstance(transport.getClassLoader(),new Class[]{transport},(proxy,method,args)->{String path=(String)args[2];JSONObject body=(JSONObject)args[3];paths.add(path);if(body!=null){writes.add(new JSONObject(body.toString()).put("route",path));return new JSONObject().put("status","accepted").put("message","已提交");}if(path.equals("/api/apps")){JSONArray apps=new JSONArray();for(String id:new String[]{"claude","codex","deepseek","assistant"})apps.put(new JSONObject().put("id",id).put("running",true));return new JSONObject().put("apps",apps);}if(path.matches("/api/native/(claude|codex|deepseek)"))return new JSONObject().put("sessions",sessions);return new JSONObject(fixture.toString());});
        ui(()->{set(app,"origin","https://fixture.trycloudflare.com");set(app,"token","fixture");set(app,"transport",mock);call("showTab",new Class[]{String.class},"codex");});await(()->require(find(getUiAutomation().getRootInActiveWindow(),"回归会话 0")!=null,"catalog loaded"));
        click("回归会话 0");await(()->require(get(app,"sessionId")!=null,"tap opens conversation"));SystemClock.sleep(700);
        ui(()->{View history=(View)get(app,"historyBar"),title=(View)get(app,"sessionTitle");Rect h=new Rect(),t=new Rect();history.getGlobalVisibleRect(h);title.getGlobalVisibleRect(t);require(history.getParent()!=get(app,"chatHeader")&&h.top>=t.bottom,"history below session title");require(((EditText)get(app,"composer")).getMinLines()==3,"composer has three lines");Button send=(Button)get(app,"sendButton");Rect visible=new Rect();send.getLocalVisibleRect(visible);require(send.getTop()>=0&&visible.height()==send.getHeight()&&visible.width()==send.getWidth(),"send circle is fully visible");require(!((LinearLayout)send.getParent()).isBaselineAligned(),"composer baseline cannot pull circle outside row");});shot("interaction-chat");
        ui(()->call("showTab",new Class[]{String.class},"codex"));SystemClock.sleep(300);ListView list=(ListView)get(app,"sessionList");float density=app.getResources().getDisplayMetrics().density;
        swipe(list,-130*density,0);ui(()->{require(get(app,"backend").equals("deepseek"),"horizontal swipe changes page");require(get(app,"sessionId")==null,"swipe does not open conversation");});
        swipe((ListView)get(app,"sessionList"),25*density,0);ui(()->{require(get(app,"backend").equals("deepseek")&&get(app,"sessionId")==null,"aborted swipe does not click a row");require(((View)get(app,"screen")).getTranslationX()==0,"canceled swipe settles");});
        int[] listPosition=new int[2];((View)get(app,"sessionList")).getLocationOnScreen(listPosition);click("DeepSeek 客户端状态，点击切换客户端");await(()->require(find(getUiAutomation().getRootInActiveWindow(),"DeepSeek · 启动")!=null,"current app control visible"));require(find(getUiAutomation().getRootInActiveWindow(),"桌面助手 · 启动")==null,"assistant absent from provider menu");
        Rect start=new Rect(),stop=new Rect();find(getUiAutomation().getRootInActiveWindow(),"DeepSeek · 启动").getBoundsInScreen(start);find(getUiAutomation().getRootInActiveWindow(),"DeepSeek · 关闭").getBoundsInScreen(stop);require(stop.top>=start.bottom,"controls arranged vertically");int[] afterMenu=new int[2];((View)get(app,"sessionList")).getLocationOnScreen(afterMenu);require(afterMenu[1]==listPosition[1],"menu overlays without shifting list");require(start.width()<app.getResources().getDisplayMetrics().widthPixels/2,"menu wraps content");click("DeepSeek · 启动");await(()->require(writes.stream().anyMatch(w->w.optString("route").equals("/api/apps/deepseek/start")),"control targets DeepSeek only"));
        ui(()->call("openSettings",new Class[]{}));click("主题配色");await(()->require(find(getUiAutomation().getRootInActiveWindow(),"主题配色网格")!=null,"theme grid visible"));View grid=findView((View)get(app,"screen"),"主题配色网格");shot("interaction-settings");ui(()->{GridLayout g=(GridLayout)grid;require(g.getColumnCount()==4&&g.getChildCount()==7,"seven themes in a four-column grid");require(g.getChildAt(0).getTop()==g.getChildAt(3).getTop()&&g.getChildAt(4).getTop()>g.getChildAt(0).getTop(),"themes wrap onto a second row in order");for(int i=0;i<7;i++){LinearLayout card=(LinearLayout)g.getChildAt(i);require(card.getChildCount()==2&&((LinearLayout)card.getChildAt(0)).getChildCount()==3,"each theme card shows canvas, primary and secondary swatches");LinearLayout caption=(LinearLayout)card.getChildAt(1);TextView captionLabel=(TextView)caption.getChildAt(caption.getChildCount()-1);require(captionLabel.length()>0,"theme card is labelled last in its caption row");if(caption.getChildCount()>1)require(caption.getChildAt(0) instanceof ImageView,"only the current theme prepends a check glyph");}});shot("interaction-settings");Class<?> overlayType=Class.forName("io.github.abyxs.codingremote.StatusOverlay");Constructor<?> constructor=overlayType.getDeclaredConstructor(Context.class);constructor.setAccessible(true);Object overlay=constructor.newInstance(app);Method update=overlayType.getDeclaredMethod("update",JSONObject.class);update.setAccessible(true);app.getSharedPreferences("ui",0).edit().putBoolean("overlay",true).putInt("overlayX",Math.round(220*density)).putInt("overlayY",Math.round(150*density)).commit();
        ui(()->app.moveTaskToBack(true));SystemClock.sleep(200);ui(()->update.invoke(overlay,new JSONObject().put("tasks",new JSONArray().put(new JSONObject().put("id","fixture").put("backend","codex").put("status","active").put("title","不应显示的会话标题").put("progress","正在检查页面滚动和布局")))));SystemClock.sleep(400);
        // AppVisibility reports hidden 200ms after the last activity stops, and the overlay
        // posts its own render, so the panel does not exist until both have happened.
        for(int i=0;i<20&&(get(overlay,"panel")==null||((LinearLayout)get(overlay,"panel")).getChildCount()==0);i++)SystemClock.sleep(100);
        ui(()->{LinearLayout panel=(LinearLayout)get(overlay,"panel");require(panel!=null&&panel.getChildCount()==1&&panel.getChildAt(0) instanceof ImageView,"collapsed overlay is a draggable cut-out pet");require(!(Boolean)get(overlay,"bubbleOpen"),"no bubble until the pet is tapped");});
        ui(()->{Method open=overlayType.getDeclaredMethod("openBubble");open.setAccessible(true);open.invoke(overlay);});SystemClock.sleep(300);ui(()->{require((Boolean)get(overlay,"bubbleOpen"),"tapping the pet opens the message bubble");View dialog=(View)get(overlay,"bubbleList");require(hasText(dialog,"正在检查页面滚动和布局"),"bubble shows live progress");require(!hasText(dialog,"不应显示的会话标题"),"running task omits the raw session title");View item=findView(dialog,"打开运行会话 fixture");require(item!=null,"bubble carries the running session");item.performClick();});SystemClock.sleep(600);
        ui(()->require("fixture".equals(get(app,"sessionId")),"progress click opens exact session"));
        ui(()->require(!(Boolean)get(overlay,"bubbleOpen"),"opening a session dismisses the bubble"));
        // Opening a session brought the app forward, and the overlay deliberately does not
        // paint over a foreground app, so it has to go back to the background to render.
        ui(()->app.moveTaskToBack(true));SystemClock.sleep(400);
        Class<?> visibilityType=Class.forName("io.github.abyxs.codingremote.AppVisibility");Method visibleMethod=visibilityType.getDeclaredMethod("visible");visibleMethod.setAccessible(true);
        for(int i=0;i<30&&(Boolean)visibleMethod.invoke(null);i++)SystemClock.sleep(100);
        ui(()->{Method open=overlayType.getDeclaredMethod("openBubble");open.setAccessible(true);open.invoke(overlay);});SystemClock.sleep(400);
        for(int i=0;i<20&&get(overlay,"bubbleList")==null;i++)SystemClock.sleep(100);
        ui(()->{View dialog=(View)get(overlay,"bubbleList");require(dialog!=null,"the bubble renders its list");});SystemClock.sleep(300);
        // The bubble has no close button: tapping the pet again is what folds it back, and
        // the pet must survive that so the overlay is still reachable afterwards.
        ui(()->{Method toggle=overlayType.getDeclaredMethod("toggleBubble");toggle.setAccessible(true);toggle.invoke(overlay);});SystemClock.sleep(300);
        ui(()->require(!(Boolean)get(overlay,"bubbleOpen")&&get(overlay,"panel")!=null,"folding the bubble leaves the pet in place"));SystemClock.sleep(100);
        ui(()->app.finish());
        result.putString("stream","PASS: title/history ordering; three-line composer and fully visible send circle; horizontal navigation and canceled-swipe click suppression; scoped vertical application menu; seven swatches; cut-out pet overlay, tap-to-dialog live progress, exact session open and close-from-dialog.\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable e){result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
    boolean hasText(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().contains(text))return true;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(hasText(((ViewGroup)v).getChildAt(i),text))return true;return false;}
    View findView(View view,String description){if(description.equals(String.valueOf(view.getContentDescription())))return view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){View found=findView(((ViewGroup)view).getChildAt(i),description);if(found!=null)return found;}return null;}
    void tap(View view){long time=SystemClock.uptimeMillis();view.dispatchTouchEvent(MotionEvent.obtain(time,time,0,12,12,0));view.dispatchTouchEvent(MotionEvent.obtain(time,time+30,1,12,12,0));}
}
